"""Part (a): one sentence per finding, fitted to the reader, generated by nobody.

Templates, with the numbers substituted from the finding's own ``evidence``. Nothing here
can hallucinate, because nothing here is written at run time — the sentences exist in this
file and only the values move.

This is the layer everything else falls back to. If no language model is configured, or if
one is and its output fails verification, the summary is built from these. So they have to
be good enough to ship on their own, not placeholders.

Why they are audience-aware
---------------------------

Because the fallback has to be *usable*, not merely safe. A fallback that produces
engineer prose for a clinician is a fallback nobody will accept, and the moment the
fallback is unacceptable the language model stops being optional. So each template is
written once per register that genuinely needs its own wording, and the
:class:`~themis_assess.summary.audience.Audience` decides which, formats the numbers, and
supplies the metric names.

Where a rule has no audience-specific template, the finding's own ``detail`` is used. That
is already a filled template — written for a technical reader — so the degradation is to
something correct and slightly dry, never to something missing.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping
from typing import Any

from themis_assess.summary.audience import Audience

__all__ = ["render_finding", "TEMPLATES", "has_template"]

#: ``{rule: {audience_name_or_"default": callable}}``. A callable takes the finding and
#: the audience and returns one or more sentences.
TEMPLATES: dict[str, dict[str, Callable[[Any, Audience], str]]] = {}


def _template(rule: str, *audiences: str) -> Callable[..., Any]:
    """Register a template for ``rule``, for the named audiences (or as the default)."""

    def register(fn: Callable[[Any, Audience], str]) -> Callable[[Any, Audience], str]:
        slot = TEMPLATES.setdefault(rule, {})
        for name in audiences or ("default",):
            slot[name] = fn
        return fn

    return register


def has_template(rule: str, audience: Audience) -> bool:
    """Whether a template exists for this rule and reader."""
    slot = TEMPLATES.get(rule, {})
    return audience.name in slot or "default" in slot


def render_finding(finding: Any, audience: Audience) -> str:
    """The sentence for one finding, in this reader's register.

    Falls back to the finding's own ``detail`` where no template matches, so a rule added
    to the library without a template here still reads correctly.
    """
    slot = TEMPLATES.get(getattr(finding, "rule", ""), {})
    template = slot.get(audience.name) or slot.get("default")
    if template is None:
        return str(getattr(finding, "detail", "")).strip()
    try:
        return template(finding, audience).strip()
    except Exception:  # noqa: BLE001 - see below
        # Deliberately broad. This is the fallback path: it is what runs when no model is
        # configured and what a rejected model's output is replaced by, so a template
        # that trips over a missing evidence key must degrade to the finding's own detail
        # rather than raise. Narrowing this to (KeyError, TypeError, ValueError) let an
        # AttributeError through and crashed the summary — found by a test that built a
        # finding with empty evidence, which is exactly what a hand-assembled finding
        # looks like.
        return str(getattr(finding, "detail", "")).strip()


def _ev(finding: Any) -> Mapping[str, Any]:
    return getattr(finding, "evidence", {}) or {}


def _require(finding: Any, *keys: str) -> Mapping[str, Any]:
    """The finding's evidence, or raise so :func:`render_finding` falls back.

    Templates have to *refuse* rather than improvise. Made tolerant of missing keys, the
    acceptance template produced "The model's the metric is not measured, short of the
    not measured that was agreed as the minimum" — grammatical, meaningless, and worse
    than the plain fallback it displaced. A template either has what it needs or it
    stands aside.
    """
    evidence = _ev(finding)
    missing = [key for key in keys if evidence.get(key) is None]
    if missing:
        raise KeyError(f"{getattr(finding, 'rule', '?')} evidence lacks {missing}")
    return evidence


# ==========================================================================
# accuracy — the acceptance verdict
# ==========================================================================


@_template("accuracy.criterion_failed", "clinician", "manager")
def _criterion_failed_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "metric", "value", "acceptable")
    metric = e.get("metric")
    value, required = audience.format_pair(metric, e.get("value"), e.get("acceptable"))
    return (
        f"{audience.metric_subject(metric)} is {value}, short of the {required} that was "
        f"agreed as the minimum. The reason that minimum was chosen: "
        f"{e.get('rationale') or 'not recorded'}."
    )


@_template("accuracy.criterion_failed")
def _criterion_failed(finding: Any, audience: Audience) -> str:
    e = _require(finding, "metric", "value", "acceptable")
    metric = e.get("metric")
    return (
        f"{metric} is {audience.format_value(metric, e.get('value'))} against a required "
        f"{audience.format_value(metric, e.get('acceptable'))}, short by "
        f"{audience.format_value(None, abs(float(e.get('margin', 0.0))))}. "
        f"Rationale on the requirement: {e.get('rationale') or 'none recorded'}."
    )


@_template("accuracy.no_criteria", "clinician", "manager", "regulator")
def _no_criteria_plain(finding: Any, audience: Audience) -> str:
    return (
        "No one has stated how good this model needs to be, so this assessment reports "
        "numbers without a verdict. Whether the figures below are acceptable is a "
        "property of how the model will be used, which the assessment cannot know."
    )


@_template("accuracy.requirement_not_measured")
def _requirement_not_measured(finding: Any, audience: Audience) -> str:
    metric = _require(finding, "metric").get("metric")
    return (
        f"A requirement was set for {audience.name_metric(metric)} and it was never "
        f"measured, so the overall verdict does not cover it. This is a gap in the "
        f"evaluation, not a fault in the model."
    )


# ==========================================================================
# accuracy — per class
# ==========================================================================


@_template("accuracy.class_error_rate", "clinician")
def _class_error_clinician(finding: Any, audience: Audience) -> str:
    e = _require(finding, "class", "error_rate")
    label, rate = e.get("class"), e.get("error_rate")
    support = e.get("support")
    count = f" of the {int(support)} such cases in the test set" if support else ""
    return (
        f"Of the cases that truly are {label}, the model misses "
        f"{audience.format_fraction(rate)}{count}. That is the number to weigh against "
        f"what a missed case costs here."
    )


@_template("accuracy.class_error_rate")
def _class_error(finding: Any, audience: Audience) -> str:
    e = _require(finding, "class", "error_rate", "recall")
    return (
        f"Class {e.get('class')} has an error rate of "
        f"{audience.format_fraction(e.get('error_rate'))} on "
        f"{int(e.get('support', 0))} sample(s), with recall "
        f"{audience.format_value('recall', e.get('recall'))}."
    )


# ==========================================================================
# accuracy — subgroups
# ==========================================================================


@_template("accuracy.subgroup_gap", "clinician", "manager")
def _subgroup_gap_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "subgroup", "metrics")
    subgroup, metrics = e.get("subgroup"), e.get("metrics") or {}
    # The widest gap among the metrics this reader can interpret, not the widest gap
    # outright — see Audience.prefers_metric for why those differ.
    worst = min(
        metrics.items(),
        key=lambda kv: (audience.prefers_metric(kv[0]), -kv[1].get("fraction", 0.0)),
        default=None,
    )
    n = e.get("n_samples")
    where = f", on {int(n)} cases," if n else ","
    if worst is None:
        return f"The model performs worst on the {subgroup} group."
    name, detail = worst
    here, overall = audience.format_pair(
        name, detail.get("in_subgroup"), detail.get("aggregate")
    )
    return (
        f"The model serves the {subgroup} group worst{where} and the widest gap is in "
        f"{audience.name_metric(name)}: {here} there against {overall} overall. An "
        f"overall figure averages the groups together and so cannot show this."
    )


@_template("accuracy.subgroup_gap")
def _subgroup_gap(finding: Any, audience: Audience) -> str:
    e = _require(finding, "subgroup", "metrics")
    metrics = e.get("metrics") or {}
    worst = sorted(metrics.items(), key=lambda kv: -kv[1].get("fraction", 0.0))[:3]
    parts = [
        f"{name} {audience.format_value(name, d.get('in_subgroup'))} against "
        f"{audience.format_value(name, d.get('aggregate'))} aggregate"
        for name, d in worst
    ]
    return (
        f"Subgroup {e.get('subgroup')!r} is the worst served on {len(metrics)} metric(s): "
        + "; ".join(parts)
        + "."
    )


# ==========================================================================
# accuracy — calibration and diagnostics
# ==========================================================================


@_template("accuracy.miscalibrated", "clinician", "manager")
def _miscalibrated_plain(finding: Any, audience: Audience) -> str:
    gap = _require(finding, "expected_calibration_error")["expected_calibration_error"]
    return (
        f"When the model states a confidence, that confidence is off by about "
        f"{audience.format_fraction(gap)} on average. This matters if the number is read "
        f"as a probability — used to rank or triage cases — and not at all if only the "
        f"predicted category is used."
    )


@_template("accuracy.errors_on_outliers", "clinician")
def _outliers_clinician(finding: Any, audience: Audience) -> str:
    e = _require(finding, "outlier_error_rate", "inlier_error_rate", "n_outliers")
    return (
        f"The model's mistakes cluster on the most unusual cases: it is wrong "
        f"{audience.format_fraction(e.get('outlier_error_rate'))} of the time on the "
        f"{int(e.get('n_outliers', 0))} least typical, against "
        f"{audience.format_fraction(e.get('inlier_error_rate'))} elsewhere. Unusual "
        f"presentations are where it should be trusted least."
    )


@_template("accuracy.uncertainty_uninformative", "clinician", "manager")
def _uncertainty_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "error_rate_flagged", "error_rate_unflagged")
    return (
        f"The model cannot tell when it is about to be wrong. The cases it reports as "
        f"least certain are wrong {audience.format_fraction(e.get('error_rate_flagged'))} "
        f"of the time, against {audience.format_fraction(e.get('error_rate_unflagged'))} "
        f"for the rest — close enough that sending the uncertain cases for human review "
        f"would be little better than picking at random."
    )


# ==========================================================================
# robustness
# ==========================================================================


@_template("robustness.tolerance_exceeded", "clinician", "manager")
def _tolerance_exceeded_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "worst_at")
    where = e.get("worst_at")
    condition = _describe_perturbation(where)
    return (
        f"The model degrades more than was agreed to be acceptable when the input data "
        f"changes. The worst case tested was {condition}. Whether that much change is "
        f"realistic here is a judgement someone who knows the data collection has to make."
    )


@_template("robustness.tolerance_exceeded")
def _tolerance_exceeded(finding: Any, audience: Audience) -> str:
    e = _require(finding, "metric", "value", "acceptable", "basis")
    metric = e.get("metric")
    return (
        f"{metric} over {e.get('accuracy_metric')} is "
        f"{audience.format_value(metric, e.get('value'))} on the {e.get('basis')} basis, "
        f"against a tolerated {audience.format_value(metric, e.get('acceptable'))}; worst "
        f"at {e.get('worst_at')}."
    )


@_template("robustness.no_tolerance", "clinician", "manager", "regulator")
def _no_tolerance_plain(finding: Any, audience: Audience) -> str:
    return (
        "How much the model is allowed to degrade when the data shifts was never stated, "
        "so this part of the assessment says how much it degrades without saying whether "
        "that is acceptable. That threshold has to come from the deployment."
    )


@_template("robustness.worst_cell", "clinician", "manager")
def _worst_cell_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "clean", "worst", "retained", "perturbation", "severity")
    metric = "balanced_accuracy"
    clean, worst = e.get("clean"), e.get("worst")
    lost = 1.0 - float(e.get("retained", 1.0))
    condition = _describe_perturbation(
        f"{e.get('perturbation')}@{e.get('severity')}"
    )
    return (
        f"In the worst condition tested — {condition} — the model's performance falls "
        f"from {audience.format_value(metric, clean)} to "
        f"{audience.format_value(metric, worst)}, a loss of "
        f"{audience.format_fraction(lost)} of what it had. The average across all the "
        f"conditions tested hides this, which is why the worst case is reported beside it."
    )


@_template("robustness.worst_cell")
def _worst_cell(finding: Any, audience: Audience) -> str:
    e = _require(finding, "clean", "worst", "retained", "perturbation", "severity")
    return (
        f"{e.get('perturbation')} at severity {e.get('severity')} is the worst cell: "
        f"{audience.format_value(None, e.get('clean'))} clean falls to "
        f"{audience.format_value(None, e.get('worst'))}, retaining "
        f"{audience.format_fraction(e.get('retained'))}."
    )


#: Plain-language descriptions of what each perturbation *is*, for readers who should
#: not have to know the library's vocabulary. Keyed by perturbation name; the severity is
#: appended by the caller. Partial — anything absent falls back to the name itself.
PERTURBATION_MEANING: dict[str, str] = {
    "gaussian_noise": "random measurement noise added to every input",
    "uniform_bias": "a systematic offset applied to the measurements, as from a miscalibrated instrument",
    "missing_values": "some measurements missing entirely",
    "category_swap": "categorical fields recorded incorrectly",
    "outlier_spikes": "occasional extreme values, as from a sensor fault",
    "sensor_drift": "measurements drifting gradually over time",
    "amplitude_scaling": "measurements systematically scaled up or down",
    "flat_sensor": "a sensor stuck at one value",
    "missing_segment": "a stretch of readings missing",
    "time_warp": "readings arriving at irregular intervals",
    "correlated_noise": "noise that affects related measurements together",
}


def _describe_perturbation(label: Any) -> str:
    """Turn ``gaussian_noise@5`` into prose a non-specialist can weigh."""
    if not label:
        return "the most severe condition tested"
    text = str(label)
    name, _, severity = text.partition("@")
    meaning = PERTURBATION_MEANING.get(name, name.replace("_", " "))
    if severity:
        return f"{meaning}, at the strongest of the five levels tested" if severity == "5" \
            else f"{meaning}, at level {severity} of 5"
    return meaning


# ==========================================================================
# sensitivity and attribution
# ==========================================================================


@_template("sensitivity.single_dominant_input", "clinician", "manager")
def _dominant_input_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "most_sensitive")
    return (
        f"The model depends disproportionately on one input, {e.get('most_sensitive')!r} "
        f"— disturbing it moves the model's output far more than disturbing any other. "
        f"If that one measurement becomes unavailable or is recorded differently, the "
        f"model is affected more than the rest of the inputs would suggest."
    )


@_template("attribution.surrogate_untrustworthy", "clinician", "manager")
def _surrogate_untrustworthy_plain(finding: Any, audience: Audience) -> str:
    return (
        "An attempt was made to characterise which kinds of case the model gets wrong, "
        "and it found no pattern: the mistakes do not share any describable combination "
        "of measurements. That is reported here rather than omitted, because the analysis "
        "was run and the honest answer is that it found nothing."
    )


@_template("attribution.error_drivers")
def _error_drivers(finding: Any, audience: Audience) -> str:
    e = _require(finding, "top_features")
    top = e.get("top_features") or []
    names = ", ".join(str(entry.get("feature")) for entry in top[:3])
    return (
        f"The cases this model gets wrong are partly predictable from their inputs, and "
        f"{names} carry that prediction. These are characteristics of the inputs it gets "
        f"wrong, not causes of it getting them wrong."
    )


# ==========================================================================
# group comparison
# ==========================================================================


@_template("groups.significant_difference", "clinician", "manager")
def _group_difference_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "p_value")
    pairs = e.get("significant_pairs") or []
    named = "; ".join(f"{p.get('left')} against {p.get('right')}" for p in pairs[:3])
    tail = f" The groups that differ: {named}." if named else ""
    return (
        f"The difference between groups is larger than chance alone would explain "
        f"(p = {float(e.get('p_value', 1.0)):.3f}).{tail} A real difference is not "
        f"automatically an important one — how large it is matters separately from "
        f"whether it is real."
    )


@_template("groups.no_significant_difference", "clinician", "manager")
def _group_no_difference_plain(finding: Any, audience: Audience) -> str:
    e = _require(finding, "p_value")
    return (
        f"The differences between groups are within what chance would produce "
        f"(p = {float(e.get('p_value', 1.0)):.3f}), so there is no clear evidence that "
        f"the model treats them differently. This is not evidence that it treats them "
        f"the same: the test may simply lack the power to tell."
    )


# ==========================================================================
# reporting — about the report, not the model
# ==========================================================================


@_template("reporting.aggregate_without_breakdown", "clinician", "manager", "regulator")
def _no_breakdown_plain(finding: Any, audience: Audience) -> str:
    return (
        "The performance figures are overall averages, with no breakdown by category or "
        "by patient group. An average is highest exactly when the largest group is well "
        "served, so it cannot reveal a group the model serves badly."
    )


@_template("reporting.calibration_on_clean_only", "clinician", "manager", "regulator")
def _clean_calibration_plain(finding: Any, audience: Audience) -> str:
    return (
        "How well the model's stated confidence matches reality was checked only on "
        "unchanged data. Confidence is usually the first thing to become unreliable when "
        "the data shifts, and it does so silently — a model that keeps claiming certainty "
        "while becoming less accurate gives nothing downstream any warning."
    )
